"""Read and write AI_DOCS/ingested/manifest.md, including the Coverage column.

Rows written before the Coverage column existed are migrated in place with the
value `unverified`. ingest.py writes `unverified` (re-ingest resets it) and
verify_coverage.py writes `complete` or `incomplete (<n> gaps)`.
"""

from __future__ import annotations

from pathlib import Path

HEADER_LINES = [
    "# Ingested files manifest",
    "",
    "Generated by the `markitdown` skill. One row per ingested source. Coverage is",
    "written by `verify_coverage.py`: a source is read only when it says `complete`.",
    "",
    "| source | type | ingested .md | ingested_at | coverage |",
    "|--------|------|--------------|-------------|----------|",
]
UNVERIFIED = "unverified"


def _cells(line: str) -> list[str]:
    """Split a Markdown table row into trimmed cells."""
    return [c.strip() for c in line.strip().strip("|").split("|")]


def _rows(manifest: Path) -> list[list[str]]:
    """Return the data rows of the manifest, migrated to five columns."""
    if not manifest.exists():
        return []
    rows = []
    for line in manifest.read_text(encoding="utf-8").splitlines():
        if not line.startswith("|") or line.startswith("|--") or line.startswith("| source |"):
            continue
        cells = _cells(line)
        if len(cells) == 4:
            cells.append(UNVERIFIED)
        if len(cells) >= 5:
            rows.append(cells[:5])
    return rows


def _write(manifest: Path, rows: list[list[str]]) -> None:
    """Write the manifest header and rows."""
    manifest.parent.mkdir(parents=True, exist_ok=True)
    body = ["| " + " | ".join(r) + " |" for r in rows]
    manifest.write_text("\n".join(HEADER_LINES + body) + "\n", encoding="utf-8")


def upsert(manifest: Path, source: str, ftype: str, out: Path, when: str, coverage: str = UNVERIFIED) -> None:
    """Insert or replace the manifest row for a source (idempotent)."""
    rows = [r for r in _rows(manifest) if r[0] != source]
    rows.append([source, ftype, out.as_posix(), when, coverage])
    _write(manifest, rows)


def set_coverage(manifest: Path, source: str, coverage: str) -> bool:
    """Set the Coverage cell of an existing row. Returns False when the row is absent."""
    rows = _rows(manifest)
    found = False
    for row in rows:
        if row[0] == source:
            row[4] = coverage
            found = True
    if found:
        _write(manifest, rows)
    return found
